import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, GPIOZeroWarning

OUTPUT_PIN = 17
POLL_INTERVAL = 1.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    _running = True

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        output = OutputDevice(OUTPUT_PIN)
    except GPIOZeroError as exc:
        print(f"Failed to initialize GPIO {OUTPUT_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                output.on()
                print(f"GPIO {OUTPUT_PIN} -> HIGH")
            except GPIOZeroError as exc:
                print(f"Error writing HIGH to GPIO {OUTPUT_PIN}: {exc}", file=sys.stderr)

            time.sleep(POLL_INTERVAL)

            if not _running:
                break

            try:
                output.off()
                print(f"GPIO {OUTPUT_PIN} -> LOW")
            except GPIOZeroError as exc:
                print(f"Error writing LOW to GPIO {OUTPUT_PIN}: {exc}", file=sys.stderr)

            time.sleep(POLL_INTERVAL)
    finally:
        try:
            output.close()
        except Exception:
            pass
        print("GPIO cleanup done.")

if __name__ == "__main__":
    main()

import signal
import sys
import time

try:
    from gpiozero import PWMOutputDevice
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

PIN_NUMBERS = [1, 2, 3, 4]
PWM_FREQ = 1000  # Hz
INTERVAL = 0.1   # seconds

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        for pin in PIN_NUMBERS:
            try:
                dev = PWMOutputDevice(pin, frequency=PWM_FREQ, initial_value=0.0)
                devices.append(dev)
            except (GPIOZeroError, GPIODeviceError) as exc:
                print(f"Error: failed to initialize PWM on GPIO {pin}: {exc}", file=sys.stderr)
                cleanup()
                sys.exit(1)

        print(f"PWM initialized on pins {PIN_NUMBERS} at {PWM_FREQ} Hz. Press Ctrl+C to stop.")

        while _running:
            for dev in devices:
                try:
                    dev.value = 0.5
                except (GPIOZeroError, GPIODeviceError) as exc:
                    print(f"Error: failed to set PWM value on GPIO {dev.pin}: {exc}", file=sys.stderr)
                    cleanup()
                    sys.exit(1)
            time.sleep(INTERVAL)

    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        cleanup()


def cleanup():
    for dev in devices:
        try:
            dev.close()
        except Exception:
            pass
    devices.clear()


if __name__ == "__main__":
    main()

