import time
import signal
import sys
from gpiozero import PWMOutputDevice

# PCA9685 constants
PWM_FREQUENCY = 1600  # Hz
NUM_CHANNELS = 16
MIN_PULSE = 1000
MAX_PULSE = 2000

# Global handle so the signal handler can release it
_pwm = None


def _validate_channel(channel):
    """Validate that channel is a valid PCA9685 channel index."""
    if not isinstance(channel, int) or not 0 <= channel < NUM_CHANNELS:
        raise ValueError(f"Invalid channel {channel!r}; must be 0..{NUM_CHANNELS - 1}")


def _validate_pulse(pulse):
    """Validate that pulse is within the documented pulse range."""
    if not isinstance(pulse, (int, float)) or not (MIN_PULSE <= pulse <= MAX_PULSE):
        raise ValueError(f"Invalid pulse {pulse!r}; must be {MIN_PULSE}..{MAX_PULSE}")


def _validate_duty(duty):
    """Validate that duty is a valid duty-cycle value."""
    if not isinstance(duty, (int, float)) or not (0.0 <= duty <= 100.0):
        raise ValueError(f"Invalid duty {duty!r}; must be 0.0..100.0")


def _validate_channel_and_pulse(channel, pulse):
    """Validate channel and pulse together."""
    _validate_channel(channel)
    _validate_pulse(pulse)


def _validate_channel_and_duty(channel, duty):
    """Validate channel and duty together."""
    _validate_channel(channel)
    _validate_duty(duty)


def _set_pwm(channel, pulse, duty):
    """Set PWM on a channel with error handling and range clamping."""
    _validate_channel_and_pulse(channel, pulse)
    _validate_channel_and_duty(channel, duty)

    # gpiozero PWMOutputDevice expects a value in [0.0, 1.0]
    normalized_pulse = (pulse - MIN_PULSE) / (MAX_PULSE - MIN_PULSE)
    normalized_duty = duty / 100.0

    try:
        _pwm[channel].value = normalized_duty
    except Exception as exc:
        raise RuntimeError(f"Failed to set PWM on channel {channel}: {exc}") from exc


def _cleanup(signum=None, frame=None):
    """Release the PCA9685 hardware on exit or interrupt."""
    global _pwm
    if _pwm is not None:
        try:
            _pwm.close()
        except Exception:
            pass
        _pwm = None
    if signum is not None:
        sys.exit(0)


def main():
    global _pwm

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)

    try:
        # Initialize the PCA9685 PWM controller via gpiozero
        _pwm = PWMOutputDevice(
            channel=0,
            frequency=PWM_FREQUENCY,
            initial_value=0.0,
        )
    except Exception as exc:
        print(f"Failed to initialize PCA9685: {exc}", file=sys.stderr)
        sys.exit(1)

    print("PCA9685 initialized. Press Ctrl+C to exit.")

    try:
        while True:
            try:
                # Example: set channel 0 to 50% duty cycle
                _set_pwm(0, 1500, 50)
                print(f"Channel 0 set to 50% duty cycle")
            except (ValueError, RuntimeError) as exc:
                print(f"Error setting PWM: {exc}", file=sys.stderr)
            time.sleep(0.05)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

