import sys
from smbus2 import SMBus

I2C_BUS = 1
AMG8833_ADDR = 0x69
READ_INTERVAL = 0.1

running = True

def handle_signal(signum, frame):
    global running
    running = False

def main():
    global running
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        bus = SMBus(I2C_BUS)
    except Exception as e:
        print(f"Error opening I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            try:
                data = bus.read_i2c_block_data(AMG8833_ADDR, 0x00, 64)
            except OSError as e:
                print(f"I2C read error: {e}", file=sys.stderr)
                time.sleep(READ_INTERVAL)
                continue

            for i in range(0, 64, 2):
                if i + 1 < len(data):
                    print(data[i], data[i + 1], end=' ')
                else:
                    print(data[i], end=' ')
            print()

            time.sleep(READ_INTERVAL)
    finally:
        bus.close()
        print("\nI2C bus closed. Exiting.")

if __name__ == "__main__":
    main()

