import serial
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600


def read_data(ser):
    """Read one line from the serial port and validate it.

    Returns the stripped string on success, or None if the read failed
    or the data is not a valid JSON object.
    """
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"Serial read error: {exc}", file=sys.stderr)
        return None

    if not raw:
        return None

    try:
        text = raw.decode('utf-8', errors='replace').strip()
    except Exception as exc:
        print(f"Decode error: {exc}", file=sys.stderr)
        return None

    if not text:
        return None

    try:
        import json
        data = json.loads(text)
    except (json.JSONDecodeError, ValueError) as exc:
        print(f"Invalid JSON: {exc}", file=sys.stderr)
        return None

    return data


def main():
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
    except serial.SerialException as exc:
        print(f"Failed to open {SERIAL_PORT}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        data = read_data(ser)
        if data is not None:
            print(f"Received: {data}")
    finally:
        try:
            ser.close()
        except Exception:
            pass


if __name__ == "__main__":
    main()

import signal
import sys
import time
from gpiozero import DistanceSensor
from gpiozero.exc import GPIOZeroError, DeviceClosed

SENSOR_PIN_1 = 17
SENSOR_PIN_2 = 22
SPEED_OF_SOUND = 34300.0  # m/s at 20 °C
CYCLES = 5
INTERVAL = 50  # seconds

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def measure_distance(sensor):
    """Return distance in metres, or None if the device is unresponsive."""
    try:
        distance = sensor.distance
    except DeviceClosed:
        return None
    except GPIOZeroError as exc:
        print(f"Sensor read error: {exc}", file=sys.stderr)
        return None
    if distance is None:
        return None
    if distance < 0.0 or distance > 4.0:
        print(f"Distance out of expected range: {distance:.3f} m", file=sys.stderr)
        return None
    return distance


def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        sensor = DistanceSensor(echo=SENSOR_PIN_1, trigger=SENSOR_PIN_2)
    except GPIOZeroError as exc:
        print(f"Failed to initialize HC-SR04: {exc}", file=sys.stderr)
        sys.exit(1)

    print("HC-SR04 initialized on GPIO 17 (echo) / GPIO 22 (trigger).")
    print(f"Running {CYCLES} cycles, {INTERVAL} s apart.\n")

    cycle = 0
    while _running and cycle < CYCLES:
        distance = measure_distance(sensor)
        if distance is not None:
            print(f"Cycle {cycle + 1}/{CYCLES}: Distance = {distance:.2f} m")
        else:
            print(f"Cycle {cycle + 1}/{CYCLES}: No valid reading")
        cycle += 1

        if _running and cycle < CYCLES:
            time.sleep(INTERVAL)

    print("\nDone.")


if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        sys.exit(1)
    finally:
        try:
            sensor.close()
        except Exception:
            pass

