import signal
import sys
import smbus2

MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
ACCEL_XOUT_H = 0x3B

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_raw_accel(mpu_bus):
    """Read raw 16-bit signed accelerometer data from the MPU6050."""
    try:
        high = mpu_bus.read_byte_data(MPU6050_ADDR, ACCEL_XOUT_H)
        low = mpu_bus.read_byte_data(MPU6050_ADDR, ACCEL_XOUT_H + 1)
        value = (high << 8) | low
        if value >= 0x8000:
            return -((0xFFFF - value) + 1)
        return value
    except OSError as e:
        raise RuntimeError(f"I2C read failed at address 0x{MPU6050_ADDR:02X}: {e}") from e

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        mpu_bus = smbus2.SMBus(1)
    except OSError as e:
        print(f"Error: cannot open I2C bus 1: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        try:
            mpu_bus.write_byte_data(MPU6050_ADDR, PWR_MGMT_1, 0)
        except OSError as e:
            print(f"Warning: could not wake MPU6050 (0x{MPU6050_ADDR:02X}): {e}", file=sys.stderr)

        try:
            x = read_raw_accel(mpu_bus)
            y = read_raw_accel(mpu_bus)
            z = read_raw_accel(mpu_bus)
            print(f"X: {x}, Y: {y}, Z: {z}")
        except RuntimeError as e:
            print(f"Error: {e}", file=sys.stderr)
            sys.exit(1)
    finally:
        try:
            mpu_bus.close()
        except OSError:
            pass

if __name__ == "__main__":
    main()

