import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
NUM_READINGS = 3
DELAY_SECONDS = 1.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_data(ser):
    try:
        data = ser.readline()
        if data:
            return data.decode('ascii', errors='replace').strip()
        return None
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        readings_taken = 0
        while _running and readings_taken < NUM_READINGS:
            data = read_data(ser)
            if data is not None:
                print(f"Reading {readings_taken + 1}: {data}")
                readings_taken += 1
            if readings_taken < NUM_READINGS and _running:
                time.sleep(DELAY_SECONDS)
    finally:
        ser.close()
        print("Serial port closed.")

if __name__ == "__main__":
    main()

