import signal
import sys
import board
import adafruit_dht

# GPIO pins (BCM numbering) for the DHT22 sensors
SENSOR_PINS = [board.D4, board.D5, board.D17, board.D23]

# Graceful-shutdown flag
_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running

    # Install signal handlers for clean exit on Ctrl-C / SIGTERM
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Initialize the DHT22 sensor on each pin
    sensors = []
    for pin in SENSOR_PINS:
        try:
            sensor = adafruit_dht.DHT22(pin, use_pulseio=False)
            sensors.append(sensor)
        except Exception as exc:
            print(f"Failed to initialize DHT22 on {pin}: {exc}", file=sys.stderr)
            # Continue with remaining sensors

    if not sensors:
        print("No DHT22 sensors initialized. Exiting.", file=sys.stderr)
        sys.exit(1)

    print("DHT22 sensors initialized. Starting readings (Ctrl-C to stop)...")

    try:
        while _running:
            for sensor in sensors:
                try:
                    temperature = sensor.temperature
                    humidity = sensor.humidity
                    if temperature is not None and humidity is not None:
                        print(f"Sensor: {sensor.pin} | Temp: {temperature:.1f} C | Humidity: {humidity:.1f} %")
                    else:
                        print(f"Sensor: {sensor.pin} | Reading failed (None returned).", file=sys.stderr)
                except RuntimeError as exc:
                    # DHT22 checksum / timing errors are common; retry next cycle
                    print(f"Sensor: {sensor.pin} | Read error: {exc}", file=sys.stderr)
                except Exception as exc:
                    print(f"Sensor: {sensor.pin} | Unexpected error: {exc}", file=sys.stderr)

            # Wait 60 seconds, but wake early if a signal arrives
            for _ in range(60):
                if not _running:
                    break
                time.sleep(1)

    finally:
        # Release every sensor we acquired
        for sensor in sensors:
            try:
                sensor.exit()
            except Exception:
                pass
        print("\nDHT22 sensors released. Exiting.")

