import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
READ_INTERVAL_SECONDS = 5

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def initialize_serial(port, baudrate):
    try:
        ser = serial.Serial(port, baudrate, timeout=1)
        print(f"Serial port {port} opened at {baudrate} baud.")
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected error opening serial port: {e}", file=sys.stderr)
        return None

def read_sensor_data(serial_port):
    try:
        data = serial_port.readline().decode('ascii', errors='replace').strip()
        if not data:
            return None
        return data
    except serial.SerialException as e:
        print(f"Serial communication error: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected error reading from serial port: {e}", file=sys.stderr)
        return None

def validate_data(data):
    try:
        value = int(data)
    except ValueError:
        print(f"Invalid data format received: {data}", file=sys.stderr)
        return None
    if not -50 <= value <= 150:
        print(f"Value out of range: {value}", file=sys.stderr)
        return None
    return value

def process_data(data):
    validated_data = validate_data(data)
    if validated_data is None:
        return None
    print(f"Sensor reading: {validated_data}")
    return validated_data

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE)
    if serial_connection is None:
        sys.exit(1)

    try:
        while _running:
            sensor_data = read_sensor_data(serial_connection)
            if sensor_data:
                process_data(sensor_data)
            time.sleep(READ_INTERVAL_SECONDS)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}", file=sys.stderr)
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

