import signal
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
READ_INTERVAL_SECONDS = 1.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def _validate_reading(raw: bytes) -> bool:
    if not raw:
        return False
    return 0 <= int.from_bytes(raw, 'big') <= 0xFFFF

def main() -> int:
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
    except serial.SerialException as exc:
        print(f"Error: could not open {SERIAL_PORT}: {exc}", file=sys.stderr)
        return 1

    print(f"Connected to {SERIAL_PORT} @ {BAUD_RATE} baud. Press Ctrl+C to stop.")

    try:
        while _running:
            try:
                raw = ser.readline()
            except serial.SerialException as exc:
                print(f"Error: serial read failed: {exc}", file=sys.stderr)
                break

            if not raw:
                continue

            if not _validate_reading(raw):
                continue

            value = int.from_bytes(raw, 'big')
            print(f"Value: {value}")

            time.sleep(READ_INTERVAL_SECONDS)
    finally:
        try:
            ser.close()
        except Exception:
            pass
        print("Serial port closed.")

    return 0

if __name__ == "__main__":
    sys.exit(main())

