import signal
import sys
import board
import adafruit_dht

# --- Configuration -----------------------------------------------------------
DHT_PINS = [board.D4, board.D17]          # BCM GPIO 4 and GPIO 17
READ_INTERVAL_S = 5

# --- Globals for cleanup -----------------------------------------------------
_running = True
_sensor = None


def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def _read_sensor(sensor):
    """Return (temperature, humidity) or (None, None) on failure."""
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        if temperature is None or humidity is None:
            return None, None
        return temperature, humidity
    except RuntimeError as exc:
        # DHT sensors frequently throw transient checksum / timing errors.
        print(f"Sensor read error: {exc}", file=sys.stderr)
        return None, None
    except Exception as exc:
        print(f"Unexpected sensor error: {exc}", file=sys.stderr)
        return None, None


def main():
    global _sensor

    # Install signal handlers for clean shutdown
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Initialise the DHT22 devices
    for pin in DHT_PINS:
        try:
            _sensor = adafruit_dht.DHT22(pin, use_pulseio=False)
        except Exception as exc:
            print(f"Failed to initialise DHT22 on {pin}: {exc}", file=sys.stderr)
            sys.exit(1)

    print("DHT22 sensors initialised on GPIO 4 and GPIO 17. Press Ctrl+C to stop.")

    try:
        while _running:
            for idx, sensor in enumerate(_sensor):
                if not _running:
                    break
                temp, hum = _read_sensor(sensor)
                if temp is not None and hum is not None:
                    print(f"Sensor {idx}: Temperature = {temp:.1f} C, Humidity = {hum:.1f} %")
                else:
                    print(f"Sensor {idx}: No valid reading.")
            if _running:
                time.sleep(READ_INTERVAL_S)
    finally:
        # Release the underlying GPIO resources
        if _sensor is not None:
            try:
                _sensor.exit()
            except Exception:
                pass
        print("\nResources released. Exiting.")


if __name__ == "__main__":
    main()

