import time
import signal
import sys
from smbus2 import SMBus

I2C_BUS = 1
TCS34725_ADDR = 0x29
READ_INTERVAL = 0.01

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def _clamp(value, lo, hi):
    return max(lo, min(hi, value))

class TCS34725:
    def __init__(self, bus, address):
        self.bus = bus
        self.address = address

    def read_color(self):
        data = self.bus.read_i2c_block_data(self.address, 0x00, 6)
        if len(data) != 6:
            raise IOError("TCS34725 returned invalid data length")
        red = _clamp(data[0] | (data[1] << 8), 0, 65535)
        green = _clamp(data[2] | (data[3] << 8), 0, 65535)
        blue = _clamp(data[4] | (data[5] << 8), 0, 65535)
        clear = _clamp(65535 - (red + green + blue), 0, 65535)
        if clear < 0 or clear > 65535:
            raise IOError("TCS34725 clear channel out of range")
        return red, green, blue, clear

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        sensor = TCS34725(bus, TCS34725_ADDR)
    except OSError as e:
        print(f"Error: TCS34725 not found at 0x{TCS34725_ADDR:02X}: {e}", file=sys.stderr)
        bus.close()
        sys.exit(1)

    try:
        while _running:
            try:
                red, green, blue, clear = sensor.read_color()
                print(f"R:{red:5d} G:{green:5d} B:{blue:5d} C:{clear:5d}")
            except OSError as e:
                print(f"Warning: read failed: {e}", file=sys.stderr)
            time.sleep(READ_INTERVAL)
    finally:
        bus.close()

if __name__ == "__main__":
    main()

