import sys
from smbus2 import SMBus

MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
ACCEL_XOUT_H = 0x3B

running = True
bus = None

def handle_signal(signum, frame):
    global running
    running = False

def read_raw_accel(bus, addr):
    data = bus.read_i2c_block_data(addr, ACCEL_XOUT_H, 6)
    raw = (data[0] << 8) | data[1]
    if raw >= 0x8000:
        raw -= 0x10000
    return raw

def main():
    global bus
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        bus = SMBus(1)
    except OSError as e:
        print(f"Error: cannot open I2C bus 1: {e}", file=sys.stderr)
        sys.exit(1)

    try:
