            bus.write_byte_data(MPU6050_ADDR, PWR_MGMT_1, 0)
        except OSError as e:
            print(f"Error: MPU6050 not responding at 0x{MPU6050_ADDR:02X}: {e}", file=sys.stderr)
            sys.exit(1)

        for i in range(3):
            if not running:
                break
            try:
                ax = read_raw_accel(bus, MPU6050_ADDR)
                print(f"Accel X: {ax}")
            except OSError as e:
                print(f"Error reading acceleration: {e}", file=sys.stderr)
                sys.exit(1)
            time.sleep(0.1)

