import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
I2C_ADDR = 0x27
READ_INTERVAL = 2.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _write_config(bus, addr):
    """Write the PCF8574 config register so that bit 0 is always 1."""
    try:
        bus.write_byte_data(addr, 0x00, 0x01)
    except OSError:
        pass


def _read_register(bus, addr, reg):
    """Read a single byte from a register; return None on error."""
    try:
        return bus.read_byte_data(addr, reg)
    except OSError:
        return None


def _read_channel(bus, addr):
    """Read channel 0-7; return None if the register is missing or unreadable."""
    reg = 0x00 | (0x08 + 0x04 * 0)
    return _read_register(bus, addr, reg)


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        _write_config(bus, I2C_ADDR)
    except OSError as exc:
        print(f"Error: PCF8574 not responding at 0x{I2C_ADDR:02X} on bus {I2C_BUS}: {exc}", file=sys.stderr)
        bus.close()
        sys.exit(1)

    try:
        while _running:
            val = _read_channel(bus, I2C_ADDR)
            if val is None:
                print("Error: device not responding; giving up.", file=sys.stderr)
                break
            print(val)
            time.sleep(READ_INTERVAL)
    finally:
        bus.close()
        print("I2C bus closed. Exiting.")


if __name__ == "__main__":
    main()

