from gpiozero import DistanceSensor
from gpiozero.exc import GPIOZeroError, DeviceClosed

# HC-SR04 ultrasonic distance sensor on GPIO 25 (BCM)
SENSOR_PIN = 25
SPEED_OF_SOUND = 34300.0  # m/s at ~20 °C
MIN_DISTANCE_M = 0.02      # 2 cm minimum range
MAX_DISTANCE_M = 4.0      # 400 cm max range for HC-SR04

sensor = None
running = True


def cleanup(signum=None, frame=None):
    """Release the sensor and exit cleanly."""
    global running, sensor
    running = False
    if sensor is not None:
        try:
            sensor.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def main():
    global sensor

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        sensor = DistanceSensor(
            echo=SENSOR_PIN,
            max_distance=MAX_DISTANCE_M,
            threshold_distance=MIN_DISTANCE_M,
        )
    except GPIOZeroError as exc:
        print(f"Failed to initialize HC-SR04 on GPIO {SENSOR_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    print(f"HC-SR04 sensor initialized on GPIO {SENSOR_PIN} (BCM). "
          f"Reading every 0.5 s. Press Ctrl+C to stop.")

    while running:
        try:
            distance_m = sensor.distance
        except DeviceClosed:
            print("Sensor device closed unexpectedly.", file=sys.stderr)
            break
        except GPIOZeroError as exc:
            print(f"Sensor read error: {exc}", file=sys.stderr)
            break

        if distance_m is None:
            print("Sensor returned None (no echo received).", file=sys.stderr)
        elif distance_m < MIN_DISTANCE_M:
            print("Sensor out of range (too close).")
        elif distance_m > MAX_DISTANCE_M:
            print("Sensor out of range (too far).")
        else:
            print(f"Distance: {distance_m:.2f} m")

        time.sleep(0.5)

    cleanup()


