import signal
import sys
import smbus2

MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
ACCEL_XOUT_H = 0x3B

running = True

def _handle_signal(signum, frame):
    global running
    running = False

def read_raw_accel(mpu_bus):
    """Read raw 16-bit signed accelerometer data from the MPU6050."""
    try:
        high = mpu_bus.read_byte_data(MPU6050_ADDR, ACCEL_XOUT_H)
        low = mpu_bus.read_byte_data(MPU6050_ADDR, ACCEL_XOUT_H + 1)
    except OSError as e:
        print(f"I2C read error at 0x{MPU6050_ADDR:02X}: {e}", file=sys.stderr)
        return None
    raw = (high << 8) | low
    if raw >= 0x8000:
        raw -= 0x10000
    return raw

def main():
    global running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        mpu_bus = smbus2.SMBus(1)
    except OSError as e:
        print(f"Failed to open I2C bus 1: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        try:
            mpu_bus.write_byte_data(MPU6050_ADDR, PWR_MGMT_1, 0)
        except OSError as e:
            print(f"Warning: could not wake MPU6050 (0x{MPU6050_ADDR:02X}): {e}", file=sys.stderr)

        raw_x = read_raw_accel(mpu_bus)
        if raw_x is None:
            print("Error: no valid reading from MPU6050.", file=sys.stderr)
            sys.exit(1)

        print(f"Raw Accelerometer Data: X={raw_x}")
    finally:
        try:
            mpu_bus.close()
        except OSError:
            pass

if __name__ == "__main__":
    main()

