import signal
import sys
import time

try:
    from gpiozero import OutputDevice
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

PIN_A = 17
PIN_B = 18
POLL_INTERVAL = 0.2

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        pin_a = OutputDevice(PIN_A)
        pin_b = OutputDevice(PIN_B)
    except (GPIOZeroError, GPIODeviceError) as exc:
        print(f"Error: failed to initialize GPIO pins {PIN_A} or {PIN_B}: {exc}", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"Unexpected error during GPIO setup: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                pin_a.on()
                pin_b.off()
                print(f"GPIO 17 HIGH, GPIO 18 LOW")
            except (GPIOZeroError, GPIODeviceError) as exc:
                print(f"Warning: failed to write GPIO 17: {exc}", file=sys.stderr)
            time.sleep(POLL_INTERVAL)

            try:
                pin_a.off()
                pin_b.on()
                print(f"GPIO 17 LOW, GPIO 18 HIGH")
            except (GPIOZeroError, GPIODeviceError) as exc:
                print(f"Warning: failed to write GPIO 18: {exc}", file=sys.stderr)
            time.sleep(POLL_INTERVAL)
    finally:
        try:
            pin_a.close()
        except Exception:
            pass
        try:
            pin_b.close()
        except Exception:
            pass
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

