import signal
import sys
import time

try:
    from gpiozero import PWMOutputDevice
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

PIN_MAP = [
    5, 6, 13, 17, 18, 22, 23, 24, 27,
]

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        for pin in PIN_MAP:
            try:
                dev = PWMOutputDevice(pin)
                dev.value = 0.0
                devices.append(dev)
                print(f"GPIO {pin}: PWM output enabled (value=0.0)")
            except (GPIODeviceError, GPIOZeroError) as exc:
                print(f"Error: failed to initialize PWM on GPIO {pin}: {exc}", file=sys.stderr)
                return 1
            except Exception as exc:
                print(f"Error: unexpected failure initializing GPIO {pin}: {exc}", file=sys.stderr)
                return 1
    except Exception as exc:
        print(f"Error: failed to initialize PWM devices: {exc}", file=sys.stderr)
        return 1

    try:
        while _running:
            print("-" * 50)
            print("PWM control loop started. Press Ctrl+C to exit.")
            print("-" * 50)

            for dev in devices:
                try:
                    current_value = dev.value
                    if 0.0 <= current_value <= 1.0:
                        print(f"GPIO {dev.pin}: Current PWM value = {current_value:.4f}")
                    else:
                        print(f"GPIO {dev.pin}: Invalid PWM value {current_value} (out of range [0.0, 1.0])", file=sys.stderr)
                except Exception as exc:
                    print(f"Error reading GPIO {dev.pin}: {exc}", file=sys.stderr)

            time.sleep(1)
    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass
        print("PWM control loop stopped. GPIO resources released.")

    return 0

if __name__ == "__main__":
    sys.exit(main())

import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
NUM_READINGS = 3
DELAY_SECONDS = 2

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_data(ser):
    try:
        data = ser.readline()
        if data:
            return data.decode('utf-8', errors='replace').strip()
        return None
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None
    except OSError as e:
        print(f"I/O error: {e}", file=sys.stderr)
        return None

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)
    except OSError as e:
        print(f"OS error opening {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        for i in range(NUM_READINGS):
            if not _running:
                break
            reading = read_data(ser)
            if reading:
                print(f"Reading {i + 1}/{NUM_READINGS}: {reading}")
            else:
                print(f"Reading {i + 1}/{NUM_READINGS}: no data")
            if i < NUM_READINGS - 1 and _running:
                time.sleep(DELAY_SECONDS)
    finally:
        if ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

import time
import signal
import sys
from smbus2 import SMBus

I2C_BUS = 1
TSL2591_ADDR = 0x29
READ_INTERVAL = 10
NUM_READINGS = 3

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def _read_tsl2591(bus):
    """Return (lux, full_spectrum) or (None, None) on failure."""
    try:
        data = bus.read_i2c_block_data(TSL2591_ADDR, 0x00, 6)
    except OSError:
        return None, None
    if len(data) != 6:
        return None, None
    raw = (data[0] << 8) | data[1]
    full = (data[2] << 8) | data[3]
    ir = (data[4] << 8) | data[5]
    if raw >= full:
        return None, None
    if ir >= full:
        return None, None
    return (full - ir) / 1.2, full

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    readings_taken = 0
    try:
        while _running and readings_taken < NUM_READINGS:
            lux, full = _read_tsl2591(bus)
            if lux is not None:
                print(f"Lux: {lux:.2f}, Full Spectrum: {full:.2f}")
                readings_taken += 1
            else:
                print("Error: invalid reading from TSL2591", file=sys.stderr)
            if _running and readings_taken < NUM_READINGS:
                time.sleep(READ_INTERVAL)
    finally:
        bus.close()
        print("I2C bus closed. Exiting.")

if __name__ == "__main__":
    main()

import time
import signal
import sys
import board
import adafruit_dht

# --- Configuration -----------------------------------------------------------
DHT_PIN = board.D4          # BCM GPIO 4 (physical pin 7)
CYCLES = 3
INTERVAL = 60              # seconds between readings

# --- Globals for cleanup -----------------------------------------------------
_sensor = None
_running = True

def _cleanup():
    """Release the DHT22 hardware if it was initialised."""
    global _sensor
    if _sensor is not None:
        try:
            _sensor.exit()
        except Exception:
            pass
        _sensor = None

def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False

def main():
    global _sensor

    # Register signal handlers for clean exit
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Initialise the DHT22 sensor
    try:
        _sensor = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
    except Exception as exc:
        print(f"Failed to initialise DHT22 on GPIO 4: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        for i in range(CYCLES):
            if not _running:
                break

            try:
                temperature = _sensor.temperature
                humidity = _sensor.humidity

                if temperature is None or humidity is None:
                    print(f"Cycle {i + 1}: DHT22 returned None (sensor absent or not ready)")
                else:
                    print(f"Cycle {i + 1}: T={temperature:.1f} °C  H={humidity:.1f} %")
            except RuntimeError as exc:
                # DHT22 checksum / timing errors are common; log and continue
                print(f"Cycle {i + 1}: DHT22 read error: {exc}")
            except Exception as exc:
                print(f"Cycle {i + 1}: Unexpected error: {exc}", file=sys.stderr)

            if i < CYCLES - 1 and _running:
                time.sleep(INTERVAL)

    finally:
        _cleanup()
        print("DHT22 resources released.")

if __name__ == "__main__":
    main()

import signal
import sys
import time

try:
    from gpiozero import PWMOutputDevice
    from gpiozero.exc import GPIOZeroError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

PIN_MAP = [14, 15, 18]
running = True


def handle_signal(signum, frame):
    global running
    running = False


def main():
    global running
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    devices = []
    try:
        for pin in PIN_MAP:
            try:
                dev = PWMOutputDevice(pin)
                dev.value = 0.0
                devices.append(dev)
            except GPIOZeroError as e:
                print(f"Error: failed to initialize PWM on GPIO {pin}: {e}", file=sys.stderr)
                cleanup()
                sys.exit(1)
    except Exception as e:
        print(f"Error: unexpected failure during initialization: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    try:
        while running:
            for dev in devices:
                dev.value = 0.5
            time.sleep(0.1)
            for dev in devices:
                dev.value = 0.0
            time.sleep(0.1)
    except Exception as e:
        print(f"Runtime error: {e}", file=sys.stderr)
    finally:
        cleanup()


