    main()

import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
ADXL345_ADDR = 0x1D
POWER_CTL = 0x2D
DATA_FORMAT = 0x31
DATAX0 = 0x32

running = True


def _handle_signal(signum, frame):
    global running
    running = False


def _write_reg(bus, reg, value):
    bus.write_byte_data(reg, 0, value)


def _read_reg(bus, reg):
    return bus.read_byte_data(reg, 0)


def _read_block(bus, reg):
    return bus.read_i2c_block_data(reg, 0, 6)


def init_adxl345(bus):
    _write_reg(bus, POWER_CTL, 0x08)
    _write_reg(bus, DATA_FORMAT, 0x08)
    _read_reg(bus, POWER_CTL)


def main():
    global running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        init_adxl345(bus)
    except OSError as exc:
        print(f"Error: ADXL345 not found at 0x{ADXL345_ADDR:02X} on bus {I2C_BUS}: {exc}", file=sys.stderr)
        bus.close()
        sys.exit(1)

    try:
        while running:
            try:
                data = _read_block(bus, DATAX0)
                x = (data[1] << 8) | data[0]
                y = (data[3] << 8) | data[2]
                z = (data[5] << 8) | data[4]
                print(f"X: {x}, Y: {y}, Z: {z}")
            except OSError as exc:
                print(f"Warning: I2C read error: {exc}", file=sys.stderr)
            time.sleep(1)
    finally:
        bus.close()


if __name__ == "__main__":
    main()

import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, GPIOZeroWarning

OUTPUT_PIN = 17
POLL_INTERVAL = 5.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    _running = True

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        output = OutputDevice(OUTPUT_PIN)
    except GPIOZeroError as exc:
        print(f"Failed to initialize GPIO {OUTPUT_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                output.on()
                print(f"GPIO {OUTPUT_PIN} -> HIGH")
            except GPIOZeroError as exc:
                print(f"Error writing HIGH to GPIO {OUTPUT_PIN}: {exc}", file=sys.stderr)

            time.sleep(POLL_INTERVAL)

            if not _running:
                break

            try:
                output.off()
                print(f"GPIO {OUTPUT_PIN} -> LOW")
            except GPIOZeroError as exc:
                print(f"Error writing LOW to GPIO {OUTPUT_PIN}: {exc}", file=sys.stderr)

            time.sleep(POLL_INTERVAL)
    finally:
        try:
            output.close()
        except Exception:
            pass
        print("GPIO cleanup done.")

if __name__ == "__main__":
    main()
